(async () => {
      const redis = getRedisClient(env);
      if (!redis) {
        return {
          detail: "REDIS_URL not configured",
          label: "Redis",
          status: "yellow" as const,
          value: "Unavailable",
        };
      }

      const startedAt = Date.now();
      try {
        const pong = await redis.ping();
        const latencyMs = Date.now() - startedAt;
        return {
          detail: `Latency ${latencyMs}ms`,
          label: "Redis",
          status: latencyMs > 400 ? "yellow" : "green",
          value: pong.toUpperCase(),
        } as const;
      } catch (error) {
        return {
          detail: error instanceof Error ? error.message : "Ping failed",
          label: "Redis",
          status: "red" as const,
          value: "Error",
        } as const;
      }
    })
